public static boolean useFluxShieldCharge(LivingEntity entity, ItemStack stack) {

        if (stack.isEmpty()) {
            return false;
        }
        IFluxShieldedItem cap = stack.getCapability(CapabilityFluxShielding.ITEM);
        if (cap != null && cap.useCharge(entity)) {
