@SubscribeEvent (priority = EventPriority.LOWEST)
    public static void handleLivingAttackEvent(LivingAttackEvent event) {

        if (event.isCanceled()) {
            return;
        }
        LivingEntity target = event.getEntity();
        DamageSource source = event.getSource();
        // Flux Shielding
        float amount = event.getAmount();
        if (amount <= 500.0F && !(target instanceof Player player && (player.isCreative() || player.isSpectator())) && !(source.is(DamageTypeTags.BYPASSES_ARMOR) && source.is(DamageTypeTags.BYPASSES_EFFECTS))) {
            ItemStack shieldedItem = FluxShieldingHelper.findShieldedItem(target);
            if (!shieldedItem.isEmpty()) {
                if (target.invulnerableTime > 0) {
                    event.setCanceled(true);
                } else if (FluxShieldingHelper.useFluxShieldCharge(target, shieldedItem)) {
                    target.invulnerableTime = 10;
                    event.setCanceled(true);
                    if (target instanceof ServerPlayer) {
                        FluxShieldingHelper.updateHUD((ServerPlayer) target);
                    }
                }
                return;
            }
        }

        // Flux Armor Helmet Damage
        if (source.is(DamageTypeTags.DAMAGES_HELMET)) {
            ItemStack helmet = target.getItemBySlot(EquipmentSlot.HEAD);
            float damage = Math.max(0.5F, amount * 0.25F);
            if (helmet.getItem() instanceof FluxArmorItem armor) {
                int use = Math.min((int) (damage * armor.getEnergyPerUse(false)), armor.getEnergyStored(helmet));
                armor.useEnergy(helmet, use, target);
            }
        }
    }

@SubscribeEvent (priority = EventPriority.LOWEST)
    public static void handleLivingHurtEvent(LivingHurtEvent event) {

        if (event.isCanceled()) {
            return;
        }
        // Flux Shielding
        DamageSource source = event.getSource();
        if (source.is(DamageTypeTags.BYPASSES_ARMOR) && source.is(DamageTypeTags.BYPASSES_EFFECTS)) {
            return;
        }
        float amount = event.getAmount();
        if (amount <= 0.0F) {
            return;
        }
        LivingEntity target = event.getEntity();
        if (FluxShieldingHelper.useFluxShieldCharge(target)) {
            event.setAmount(Math.max(amount - 500.0F, 0));
            if (target instanceof ServerPlayer) {
                FluxShieldingHelper.updateHUD((ServerPlayer) target);
            }
        } else if (!source.is(DamageTypeTags.BYPASSES_ARMOR)) { // Flux Armor Damage
            float damage = Math.max(0.5F, amount * 0.25F);
            target.getArmorSlots().forEach(stack -> {
                if (stack.getItem() instanceof FluxArmorItem armor) {
                    int use = Math.min((int) (damage * armor.getEnergyPerUse(false)), armor.getEnergyStored(stack));
                    armor.useEnergy(stack, use, target);
                }
            });
        }
    }

public static boolean markEntityAsHandled(Entity e)
	{
		MutableLong currentTick;
		IntSet entitiesHandledInCurrentTick;
		if(e.level().isClientSide)
		{
			currentTick = currentTickClient;
			entitiesHandledInCurrentTick = entitiesHandledInCurrentTickClient;
		}
		else
		{
			currentTick = currentTickServer;
			entitiesHandledInCurrentTick = entitiesHandledInCurrentTickServer;
		}
		long now = e.level().getGameTime();
		if(now!=currentTick.getValue())
		{
			currentTick.setValue(now);
			entitiesHandledInCurrentTick.clear();
		}
		return entitiesHandledInCurrentTick.add(e.getId());
	}

default void onEntityCollision(@Nonnull Entity entity)
	{
		if(!isActive()||!entity.isAlive())
			return;
		if(entity instanceof Player player&&(player.isShiftKeyDown()||player.getAbilities().flying))
			return;
		PlayerUtils.resetFloatingState(entity);
		ConveyorDirection conveyorDirection = getConveyorDirection();
		float heightLimit = conveyorDirection==ConveyorDirection.HORIZONTAL?.25f: 1f;
		BlockPos pos = getBlockEntity().getBlockPos();
		final double relativeHeight = entity.getY()-pos.getY();
		if(relativeHeight >= 0&&relativeHeight < heightLimit)
		{
			boolean hasBeenHandled = !ConveyorHandler.markEntityAsHandled(entity);
			final boolean outputBlocked = isOutputBlocked();
			Vec3 vec = this.getDirection(entity, outputBlocked);
			if(entity.fallDistance < 3)
				entity.fallDistance = 0;
			if(outputBlocked)
			{
				double replacementX;
				double replacementZ;
				if(hasBeenHandled)
				{
					replacementX = entity.getDeltaMovement().x;
					replacementZ = entity.getDeltaMovement().z;
				}
				else
				{
					replacementX = 0;
					replacementZ = 0;
				}
				vec = new Vec3(
						replacementX,
						vec.y,
						replacementZ
				);
			}
			entity.setDeltaMovement(vec);
			double distX = Math.abs(pos.relative(getFacing()).getX()+.5-entity.getX());
			double distZ = Math.abs(pos.relative(getFacing()).getZ()+.5-entity.getZ());
			double threshold = .9;
			boolean contact = getFacing().getAxis()==Axis.Z?distZ < threshold: distX < threshold;
			Level w = Preconditions.checkNotNull(getBlockEntity().getLevel());
			BlockPos upPos = pos.relative(getFacing()).above();
			if(contact&&conveyorDirection==ConveyorDirection.UP&&
					!Block.isFaceFull(w.getBlockState(upPos).getShape(w, upPos), Direction.DOWN))
			{
				double move = .4;
				entity.setPos(entity.getX()+move*getFacing().getStepX(), entity.getY()+1*move, entity.getZ()+move*getFacing().getStepZ());
			}
			if(!contact)
				ConveyorHandler.applyMagnetSuppression(entity, (IConveyorBlockEntity<?>)getBlockEntity());
			else
			{
				BlockPos nextPos = getBlockEntity().getBlockPos().relative(getFacing());
				if(!(SafeChunkUtils.getSafeBE(getBlockEntity().getLevel(), nextPos) instanceof IConveyorBlockEntity))
					ConveyorHandler.revertMagnetSuppression(entity, (IConveyorBlockEntity<?>)getBlockEntity());
			}

			// In the first tick this could be an entity the conveyor belt just dropped, causing #3023
			if(entity instanceof ItemEntity item&&entity.tickCount > 1)
			{
				if(!contact)
				{
					ItemAgeAccessor access = ConveyorHandler.ITEM_AGE_ACCESS.get();
					if(item.getAge() > item.lifespan-60*20&&!outputBlocked)
						access.setAge(item, item.lifespan-60*20);
				}
				else if(!w.isClientSide)
					handleInsertion(item, conveyorDirection, distX, distZ);
			}
		}
	}

@Override
	public void onEntityCollision(@Nonnull Entity entity)
	{
		collisionTracker.onEntityCollided(entity);
		if(!isActive()||!entity.isAlive())
			return;
		if(entity instanceof Player&&entity.isShiftKeyDown())
			return;

		BlockPos posWall = getBlockEntity().getBlockPos().relative(getFacing());
		double d = .625+entity.getBbWidth();
		double distToWall = Math.abs((getFacing().getAxis()==Axis.Z?posWall.getZ(): posWall.getX())+.5-(getFacing().getAxis()==Axis.Z?entity.getZ(): entity.getX()));
		if(distToWall > d)
		{
			super.onEntityCollision(entity);
			return;
		}

		boolean outputBlocked = isOutputBlocked();
		double distY = Math.abs(getBlockEntity().getBlockPos().offset(0, 1, 0).getY()+.5-entity.getY());
		double treshold = .9;
		boolean contact = distY < treshold;

		entity.setOnGround(false);
		if(entity.fallDistance < 3)
			entity.fallDistance = 0;
		else
			entity.fallDistance *= .9;
		Vec3 vec = getDirection(entity, outputBlocked);
		boolean hasBeenHandled = !ConveyorHandler.markEntityAsHandled(entity);
		if(outputBlocked&&entity.getY() >= getBlockEntity().getBlockPos().getY()+0.25)
		{
			double my;
			if(entity.getY() < entity.yOld)
				my = entity.yOld-entity.getY();
			else
				my = entity.getDeltaMovement().y;
			if(hasBeenHandled)
				vec = new Vec3(vec.x, my, vec.z);
			else
				vec = new Vec3(0, my, 0);
		}
		entity.setDeltaMovement(vec);

		if(!contact)
			ConveyorHandler.applyMagnetSuppression(entity, (IConveyorBlockEntity)getBlockEntity());
		else
		{
			BlockPos posTop = getBlockEntity().getBlockPos().offset(0, 1, 0);
			if(!((getBlockEntity().getLevel().getBlockEntity(posTop) instanceof IConveyorBlockEntity)||(getBlockEntity().getLevel().isEmptyBlock(posTop)&&(getBlockEntity().getLevel().getBlockEntity(posTop.relative(getFacing())) instanceof IConveyorBlockEntity))))
				ConveyorHandler.revertMagnetSuppression(entity, (IConveyorBlockEntity)getBlockEntity());
		}

		if(entity instanceof ItemEntity item)
		{
			if(!contact)
			{
				if(item.getAge() > item.lifespan-60*20)
					((ItemEntityAccess)item).setAge(item.lifespan-60*20);
			}
			else
			{
				BlockPos outputPos = getBlockEntity().getBlockPos().offset(0, 1, 0);
				BlockEntity inventoryTile = getBlockEntity().getLevel().getBlockEntity(outputPos);
				if(!getBlockEntity().getLevel().isClientSide)
				{
					if(!(inventoryTile instanceof IConveyorBlockEntity))
						ItemUtils.tryInsertEntity(getBlockEntity().getLevel(), outputPos, Direction.DOWN, item);
				}
			}
		}

		if(isCovered()&&entity instanceof ItemEntity item)
			item.setPickUpDelay(10);
	}

@SubscribeEvent
    public static void onFall(LivingFallEvent event) {
        LivingEntity entity = event.getEntity();
        if (entity == null || !entity.hasEffect(ModPotions.BOUNCE_EFFECT)) {
            return;
        }
        boolean isPlayer = entity instanceof Player;
        boolean isClient = entity.level.isClientSide;
        if (isClient && !isPlayer) {
            return;
        }
        if (event.getDistance() > 2) {
            if (entity.isCrouching()) {
                event.setDamageMultiplier(0.0f);
            } else {
                event.setDamageMultiplier(0);
                entity.fallDistance = 0.0F;
                if (!isPlayer || isClient) {
                    double f = 0.95d - .1 * entity.getEffect(ModPotions.BOUNCE_EFFECT).getAmplifier();
                    // only slow down half as much when bouncing
                    entity.setDeltaMovement(entity.getDeltaMovement().x / f, entity.getDeltaMovement().y * (-0.9), entity.getDeltaMovement().z / f);
                    entity.hurtMarked = true;
                    entity.setOnGround(false);
                }
                if (isClient) {
                    EventQueue.getClientQueue().addEvent(new BounceTimedEvent(entity, entity.getDeltaMovement().y));
                } else {
                    EventQueue.getServerInstance().addEvent(new BounceTimedEvent(entity, entity.getDeltaMovement().y));
                }
                event.setCanceled(true);
            }
        }
    }

@Override
