            double f = 0.91d + 0.025d;
            Vec3 vec3d = this.livingEntity.getDeltaMovement();
            this.livingEntity.setDeltaMovement(vec3d.x / f, oldY, vec3d.z / f);
            this.livingEntity.hurtMarked = true;
        }
    }

@Override
