private static int getIdentifier(Player entity) {
        return entity.level().isClientSide ? -entity.getId() : entity.getId();
    }

public static boolean hasApplicableItem(LivingEntity player) {
        return isApplicableItem(player.getMainHandItem()) || isApplicableItem(player.getOffhandItem());
    }

public static boolean isDrawing(Player player) {
        ItemStack itemStack = player.getUseItem();
        return CastOptional.cast(itemStack.getItem(), ModularBowItem.class)
                .map(item -> item.getProgress(itemStack, player) < 1)
                .orElse(false);
    }

public static void onLivingDamage(LivingDamageEvent event) {
        if (event.getAmount() > 0
                && !event.getSource().is(DamageTypes.DROWN)
                && event.getEntity() instanceof Player player) {
            cache.invalidate(getIdentifier(player));
        }
    }

public static void onFireArrow(Player player, ItemStack itemStack) {
        boolean hasEcho = CastOptional.cast(itemStack.getItem(), ModularItem.class)
                .filter(item -> item.getEffectLevel(itemStack, ItemEffect.focusEcho) > 0)
                .isPresent();

        if (!hasEcho) {
            cache.invalidate(getIdentifier(player));
        }
    }

public static float getSpreadReduction(Player player, ItemStack itemStack) {
        Integer duration = cache.getIfPresent(getIdentifier(player));
        if (duration != null) {
            return CastOptional.cast(itemStack.getItem(), ModularItem.class)
                    .map(item -> (float) item.getEffectEfficiency(itemStack, ItemEffect.focus) * duration / 20f)
                    .orElse(0f);
        }
        return 0;
    }

protected void fireArrow(ItemStack itemStack, Level world, LivingEntity entity, int timeLeft) {
        if (entity instanceof Player) {
            Player player = (Player) entity;
            ItemStack ammoStack = player.getProjectile(vanillaBow);

            boolean playerInfinite = isInfinite(player, itemStack, ammoStack);

            // multiply by 20 to align progress with vanilla bow (fully drawn at 1sec/20ticks)
            int drawProgress = Math.round(getProgress(itemStack, entity) * 20);
            drawProgress = net.minecraftforge.event.ForgeEventFactory.onArrowLoose(itemStack, world, player, drawProgress,
                    !ammoStack.isEmpty() || playerInfinite);

            if (drawProgress < 0) {
                return;
            }

            if (!ammoStack.isEmpty() || playerInfinite) {
                if (ammoStack.isEmpty()) {
                    ammoStack = new ItemStack(Items.ARROW);
                }

                double strength = getDrawStrength(entity, itemStack);
                float velocityBonus = getEffectLevel(itemStack, ItemEffect.velocity) / 100f;
                int suspendLevel = getEffectLevel(itemStack, ItemEffect.suspend);
                ArrowItem ammoItem = CastOptional.cast(ammoStack.getItem(), ArrowItem.class)
                        .orElse((ArrowItem) Items.ARROW);
                boolean infiniteAmmo = player.getAbilities().instabuild || ammoItem.isInfinite(ammoStack, itemStack, player);

                ModularLooseProjectilesEvent looseProjectilesEvent = new ModularLooseProjectilesEvent(itemStack, ammoStack, player, world,
                        drawProgress, strength, suspendLevel > 0,
                        getArrowVelocity(drawProgress, strength, getEffectLevel(itemStack, ItemEffect.velocity) / 100f, suspendLevel > 0),
                        getEffectEfficiency(itemStack, ItemEffect.multishot),
                        Math.max(0, 100 - getEffectEfficiency(itemStack, ItemEffect.spread) - FocusEffect.getSpreadReduction(player, itemStack)),
                        player.getAbilities().instabuild || ammoItem.isInfinite(ammoStack, itemStack, player),
                        Mth.clamp(getEffectLevel(itemStack, ItemEffect.multishot), 1, infiniteAmmo ? 64 : ammoStack.getCount()),
                        player.getXRot(),
                        player.getYRot());
                MinecraftForge.EVENT_BUS.post(looseProjectilesEvent);

                ammoStack = looseProjectilesEvent.getAmmoStack();
                ImmutableList<Function<AbstractArrow, AbstractArrow>> projectileRemappers = looseProjectilesEvent.getProjectileRemappers();

                strength = looseProjectilesEvent.getStrength();
                boolean hasSuspend = looseProjectilesEvent.isHasSuspend();
                float projectileVelocity = looseProjectilesEvent.getProjectileVelocity();
                double multishotSpread = looseProjectilesEvent.getMultishotSpread();
                float accuracy = looseProjectilesEvent.getAccuracy();
                infiniteAmmo = looseProjectilesEvent.isInfiniteAmmo();
                int count = looseProjectilesEvent.getCount();
                double basePitch = looseProjectilesEvent.getBasePitch();
                double baseYaw = looseProjectilesEvent.getBaseYaw();

                if (projectileVelocity > 0.1f) {
                    if (!world.isClientSide) {
                        int powerLevel = EnchantmentHelper.getTagEnchantmentLevel(Enchantments.POWER_ARROWS, itemStack);
                        int punchLevel = EnchantmentHelper.getTagEnchantmentLevel(Enchantments.PUNCH_ARROWS, itemStack);
                        int flameLevel = EnchantmentHelper.getTagEnchantmentLevel(Enchantments.FLAMING_ARROWS, itemStack);
                        int piercingLevel = getEffectLevel(itemStack, ItemEffect.piercing)
                                + EnchantmentHelper.getTagEnchantmentLevel(Enchantments.PIERCING, itemStack);

                        for (int i = 0; i < count; i++) {
                            double yaw = baseYaw - multishotSpread * (count - 1) / 2f + multishotSpread * i;
                            fireProjectile(itemStack, world, (ArrowItem) ammoStack.getItem(), ammoStack, projectileRemappers, player,
                                    (float) basePitch, (float) yaw, projectileVelocity, accuracy, drawProgress, strength, powerLevel, punchLevel,
                                    flameLevel, piercingLevel, hasSuspend, infiniteAmmo);
                        }


                        applyDamage(1, itemStack, player);
                        applyNegativeUsageEffects(entity, itemStack, 1);

                        // max draw at 20, has to be drawn at least 3/4th for positive effects
                        if (drawProgress > 15) {
                            applyPositiveUsageEffects(entity, itemStack, 1);
                        }
                    }

                    float pitchBase = projectileVelocity;
                    if (velocityBonus > 0) {
                        pitchBase -= pitchBase * velocityBonus;
                    } else if (hasSuspend) {
                        pitchBase = pitchBase / 2;
                    }
                    world.playSound(null, player.getX(), player.getY(), player.getZ(),
                            SoundEvents.ARROW_SHOOT, SoundSource.PLAYERS,
                            0.8F + projectileVelocity * 0.2f,
                            1.9f + world.random.nextFloat() * 0.2F - pitchBase * 0.8F);

                    if (!infiniteAmmo && !player.getAbilities().instabuild) {
                        ammoStack.shrink(count);
                        if (ammoStack.isEmpty()) {
                            player.getInventory().removeItem(ammoStack);
                        }
                    }

                    FocusEffect.onFireArrow(player, itemStack);

                    player.awardStat(Stats.ITEM_USED.get(this));
                }
            }
        }
    }

@Override
    public void releaseUsing(ItemStack itemStack, Level world, LivingEntity entity, int timeLeft) {
        int usedTicks = getUseDuration(itemStack) - timeLeft;
        if (getEffectLevel(itemStack, ItemEffect.overbowed) > 0 && exceedsOverbowedLimit(entity, itemStack, usedTicks)) {
            entity.stopUsingItem();
            // trigger a small cooldown here to avoid the bow getting drawn again instantly
            CastOptional.cast(entity, Player.class).ifPresent(player -> player.getCooldowns().addCooldown(this, 10));
        } else {
            fireArrow(itemStack, world, entity, timeLeft);
        }
    }

@Override
    public void onUseTick(Level level, LivingEntity entity, ItemStack itemStack, int count) {
        if (getEffectLevel(itemStack, ItemEffect.releaseLatch) > 0 && getProgress(itemStack, entity) >= 1) {
            entity.releaseUsingItem();
        } else {
            int usedTicks = getUseDuration(itemStack) - count;
            if (getEffectLevel(itemStack, ItemEffect.overbowed) > 0 && exceedsOverbowedLimit(entity, itemStack, usedTicks)) {
                entity.stopUsingItem();
                // trigger a small cooldown here to avoid the bow getting drawn again instantly
                CastOptional.cast(entity, Player.class).ifPresent(player -> player.getCooldowns().addCooldown(this, 10));
            }
        }
    }

@SubscribeEvent(priority = EventPriority.HIGHEST) // Prevents all spells so it comes before everything else
	public static void onSpellCastPreEvent(SpellCastEvent.Pre event){
		// Arcane jammer has a chance to prevent spell casting
		// We can't just use a straight-up random number because otherwise people can spam it to get it to cast
		// Instead, we're using the world time to make blocks of time when spells will and won't work
		random.setSeed(event.getWorld().getTotalWorldTime() / UPDATE_INTERVAL);
		// For some unfathomable reason, the first call to this after setting the seed remains the same for long
		// sequences of consecutive seeds, so let's clear it out first to get to a more changeable value
		random.nextInt(2);

		if(event.getCaster() != null && event.getCaster().isPotionActive(WizardryPotions.arcane_jammer)
				// Arcane jammer I has a 1/2 chance, level II has a 2/3 chance, and so on
				&& random.nextInt(event.getCaster().getActivePotionEffect(WizardryPotions.arcane_jammer).getAmplifier() + 2) > 0){

			event.setCanceled(true);

			// TODO: This currently doesn't play nicely with continuous or charge-up spells
			if(event.getSource() == Source.WAND || event.getSource() == Source.SCROLL){
				event.getCaster().setActiveHand(EnumHand.MAIN_HAND);
			}

			// Because we're using a seed that should be consistent, we can do client-side stuff!
			event.getWorld().playSound(event.getCaster().posX, event.getCaster().posY, event.getCaster().posZ,
					WizardrySounds.MISC_SPELL_FAIL, WizardrySounds.SPELLS, 1, 1, false);

			if(event.getWorld().isRemote){

				Vec3d centre = event.getCaster().getPositionEyes(1).add(event.getCaster().getLookVec());

				for(int i = 0; i < 5; i++){
					double x = centre.x + 0.5f * (event.getWorld().rand.nextFloat() - 0.5f);
					double y = centre.y + 0.5f * (event.getWorld().rand.nextFloat() - 0.5f);
					double z = centre.z + 0.5f * (event.getWorld().rand.nextFloat() - 0.5f);
					event.getWorld().spawnParticle(EnumParticleTypes.SMOKE_LARGE, x, y, z, 0, 0, 0);
				}
			}
		}
	}

