@Override
    protected @NotNull ItemInteractionResult useItemOn(@NotNull ItemStack pStack, @NotNull BlockState state, @NotNull Level worldIn, @NotNull BlockPos pos, @NotNull Player player, @NotNull InteractionHand handIn, @NotNull BlockHitResult pHitResult) {
        if (handIn != InteractionHand.MAIN_HAND) {
            return ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;
        }
        if (worldIn.isClientSide)
            return ItemInteractionResult.SUCCESS;
        ItemStack stack = player.getItemInHand(handIn);
        if (SpellCasterRegistry.from(stack) != null) {
            Spell spell = SpellCasterRegistry.from(stack).getSpell();
            if (!spell.isEmpty()) {
                if (spell.getCastMethod() == null) {
                    PortUtil.sendMessage(player, Component.translatable("ars_nouveau.alert.turret_needs_form"));
                    return ItemInteractionResult.SUCCESS;
                }
                if (!(TURRET_BEHAVIOR_MAP.containsKey(spell.getCastMethod()))) {
                    PortUtil.sendMessage(player, Component.translatable("ars_nouveau.alert.turret_type"));
                    return ItemInteractionResult.SUCCESS;
                }
                if (worldIn.getBlockEntity(pos) instanceof BasicSpellTurretTile tile) {
                    tile.setSpell(spell);
                    tile.setPlayer(player.getUUID());
                    tile.updateBlock();
                    PortUtil.sendMessage(player, Component.translatable("ars_nouveau.alert.spell_set"));
                    worldIn.sendBlockUpdated(pos, state, state, 2);
                }
            }
        }
        return super.useItemOn(pStack, state, worldIn, pos, player, handIn, pHitResult);
    }

public void shootSpell() {
        BlockPos pos = this.getBlockPos();

        if (spellCaster.getSpell().isEmpty() || !(this.level instanceof ServerLevel level))
            return;
        int manaCost = getManaCost();
        if (manaCost > 0) {
            var sp = this.getLinkedSourceProvider();
            if (this.level instanceof ServerLevel serverLevel && sp != null) {
                var cap = this.level.getCapability(CapabilityRegistry.SOURCE_CAPABILITY, sp.first(), sp.second().orElse(null));
                if (cap == null) {
                    this.setLinkedSourceProvider(null);
                    return;
                }

                if (cap.extractSource(manaCost, true) < manaCost) {
                    return;
                }

                cap.extractSource(manaCost, false);
                EntityFollowProjectile.spawn(serverLevel, sp.first(), this.worldPosition);
            } else if (SourceUtil.takeSourceMultipleWithParticles(pos, level, 10, manaCost) == null) {
                return;
            }
        }

        Networking.sendToNearbyClient(level, pos, new PacketOneShotAnimation(pos));
        Position iposition = BasicSpellTurret.getDispensePosition(pos, level.getBlockState(pos).getValue(BasicSpellTurret.FACING));
        Direction direction = level.getBlockState(pos).getValue(BasicSpellTurret.FACING);
        FakePlayer fakePlayer = uuid != null
                ? FakePlayerFactory.get(level, new GameProfile(uuid, ""))
                : ANFakePlayer.getPlayer(level);
        fakePlayer.setPos(pos.getX(), pos.getY(), pos.getZ());
        EntitySpellResolver resolver = new EntitySpellResolver(new SpellContext(level, spellCaster.getSpell(), fakePlayer, new TileCaster(this, SpellContext.CasterType.TURRET)));
        if (resolver.castType != null && BasicSpellTurret.TURRET_BEHAVIOR_MAP.containsKey(resolver.castType)) {
            BasicSpellTurret.TURRET_BEHAVIOR_MAP.get(resolver.castType).onCast(resolver, level, pos, fakePlayer, iposition, direction);
        }
    }

public static void conjure(SpellContext context, @Nullable Number timeVal, BlockPos pos, Level world, BlockState state) {
		if(world.getBlockState(pos).getBlock() != state.getBlock()) {
			if(conjure(world, pos, context.caster, state)) {
				if(timeVal != null && timeVal.intValue() > 0) {
					int val = timeVal.intValue();
					world.scheduleTick(pos, state.getBlock(), val);
				}

				BlockEntity tile = world.getBlockEntity(pos);

				ItemStack cad = PsiAPI.getPlayerCAD(context.caster);
				if(tile instanceof TileConjured && !cad.isEmpty()) {
					((TileConjured) tile).colorizer = ((ICAD) cad.getItem()).getComponentInSlot(cad, EnumCADComponent.DYE);
				}

			}
		}
	}

public static boolean conjure(Level world, BlockPos pos, Player player, BlockState state) {
		if(world.getChunk(SectionPos.blockToSectionCoord(pos.getX()), SectionPos.blockToSectionCoord(pos.getZ()), ChunkStatus.FULL, false) == null || !world.mayInteract(player, pos)) {
			return false;
		}

		BlockState inWorld = world.getBlockState(pos);
		if(inWorld.isAir() || inWorld.canBeReplaced()) {
			return world.setBlockAndUpdate(pos, state);
		}
		return false;
	}

@Override
	public Object execute(SpellContext context) throws SpellRuntimeException {
		Vector3 positionVal = this.getParamValue(context, position);
		Number timeVal = this.getParamValue(context, time);

		if(positionVal == null) {
			throw new SpellRuntimeException(SpellRuntimeException.NULL_VECTOR);
		}
		if(!context.isInRadius(positionVal)) {
			throw new SpellRuntimeException(SpellRuntimeException.OUTSIDE_RADIUS);
		}

		BlockPos pos = positionVal.toBlockPos();

		Level world = context.focalPoint.getCommandSenderWorld();

		if(!world.mayInteract(context.caster, pos)) {
			return null;
		}

		conjure(context, timeVal, pos, world, messWithState(ModConjuredBlock.BLOCK.get().defaultBlockState()));

		return null;
	}

